def normalize_path(path: str) -> str:
    """
    Normalize a Unix-style POSIX path string by resolving . and ..
    components and collapsing redundant separators.
    """
    if not path:
        return "."

    is_absolute = path.startswith("/")

    # Split and filter empty parts (handles multiple slashes and trailing slash)
    parts = [p for p in path.split("/") if p != ""]

    stack = []
    for part in parts:
        if part == ".":
            # Skip current directory references
            continue
        elif part == "..":
            if is_absolute:
                # At root, .. stays at root
                if stack:
                    stack.pop()
                # else: already at root, do nothing
            else:
                # Relative path: if stack has a real component (not ".."), pop it
                if stack and stack[-1] != "..":
                    stack.pop()
                else:
                    # Preserve leading .. components
                    stack.append("..")
        else:
            stack.append(part)

    if is_absolute:
        return "/" + "/".join(stack)
    else:
        result = "/".join(stack)
        return result if result else "."
